#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long q;
    cin >> n >> q;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<vector<long long>> qs(q, vector<long long>(2));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> qs[i][j];
        }
    }

    int size = 1;
    while (size < n + 2) size *= 2;
    vector<int> mn(2 * size, -1);
    vector<vector<int>> byR(n);
    for (long long j = 0; j < q; j++) byR[qs[j][1] - 1].push_back((int)j);
    vector<int> ans(q, 0);
    for (int pos = 0; pos < n; pos++) {
        long long v = a[pos];
        if (v <= n) {
            int i = (int)v + size;
            mn[i] = pos;
            for (i >>= 1; i > 0; i >>= 1) mn[i] = min(mn[2 * i], mn[2 * i + 1]);
        }
        for (size_t k = 0; k < byR[pos].size(); k++) {
            int j = byR[pos][k];
            int l = (int)qs[j][0] - 1;
            int node = 1;
            while (node < size) {
                if (mn[2 * node] < l) node = 2 * node;
                else node = 2 * node + 1;
            }
            ans[j] = node - size;
        }
    }
    string out;
    for (long long j = 0; j < q; j++) {
        if (j > 0) out += " ";
        out += to_string(ans[j]);
    }
    cout << out << "\n";

    return 0;
}

