import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[][] qs = new long[(int) q][2];
        for (int i = 0; i < qs.length; i++) {
            for (int j = 0; j < qs[i].length; j++) {
                qs[i][j] = Long.parseLong(next());
            }
        }

        int cn = (int) n, qq = (int) q;
        int size = 1;
        while (size < cn + 2) size *= 2;
        int[] mn = new int[2 * size];
        Arrays.fill(mn, -1);
        long[] keys = new long[qq];
        for (int j = 0; j < qq; j++) keys[j] = ((qs[j][1] - 1) << 16) | j;
        Arrays.sort(keys);
        int[] ans = new int[qq];
        int next = 0;
        for (int pos = 0; pos < cn; pos++) {
            long v = a[pos];
            if (v <= cn) {
                int i = (int) v + size;
                mn[i] = pos;
                for (i >>= 1; i > 0; i >>= 1) mn[i] = Math.min(mn[2 * i], mn[2 * i + 1]);
            }
            while (next < qq && (keys[next] >> 16) == pos) {
                int j = (int) (keys[next] & 65535);
                int l = (int) qs[j][0] - 1;
                int node = 1;
                while (node < size) {
                    if (mn[2 * node] < l) node = 2 * node;
                    else node = 2 * node + 1;
                }
                ans[j] = node - size;
                next++;
            }
        }
        StringBuilder out = new StringBuilder();
        for (int j = 0; j < qq; j++) {
            if (j > 0) out.append(" ");
            out.append(ans[j]);
        }
        System.out.println(out);
    }
}
